// Dump returns diagnostic information about the connection pool.
// Returns a map with addresses as keys and connection statistics as values.
func (p *connPool) Dump() map[string]interface{} {
	result := make(map[string]interface{})
	result["pool_size"] = p.size
	result["remote_service"] = p.remoteService

	connections := make(map[string]interface{})
	p.conns.Range(func(key, value interface{}) bool {
		addr := key.(string)
		trans := value.(*transports)

		activeCount := 0
		for i := 0; i < int(trans.size); i++ {
			if trans.cliTransports[i] != nil {
				if trans.cliTransports[i].(grpc.IsActive).IsActive() {
					activeCount++
				}
			}
		}

		connections[addr] = map[string]interface{}{
			"total_slots":       trans.size,
			"active_connections": activeCount,
			"current_index":     atomic.LoadUint32(&trans.index),
		}
		return true
	})

	result["connections"] = connections
	return result
}

