// connError returns ConnectionError(code) but first
// stashes away a public reason to the caller can optionally relay it
// to the peer before hanging up on them. This might help others debug
// their implementations.
func (fr *Framer) connError(code http2.ErrCode, reason string) error {
	fr.errDetail = errors.New(reason)
	return http2.ConnectionError(code)
}

// connErrorWithPayload returns ConnectionError(code) with enhanced diagnostics
// including a hex dump of the problematic payload for debugging.
func (fr *Framer) connErrorWithPayload(code http2.ErrCode, reason string, payload []byte) error {
	const maxDumpSize = 64 // limit hex dump to first 64 bytes
	dumpLen := len(payload)
	if dumpLen > maxDumpSize {
		dumpLen = maxDumpSize
	}

	hexDump := formatHexDump(payload[:dumpLen])
	enhancedReason := fmt.Sprintf("%s\nFrame payload hex dump (first %d bytes):\n%s", reason, dumpLen, hexDump)
	if len(payload) > maxDumpSize {
		enhancedReason += fmt.Sprintf("\n... (%d more bytes omitted)", len(payload)-maxDumpSize)
	}

	fr.errDetail = errors.New(enhancedReason)
	return http2.ConnectionError(code)
}

// formatHexDump formats byte slice as hex dump for debugging
func formatHexDump(data []byte) string {
	if len(data) == 0 {
		return "(empty)"
	}

	var sb strings.Builder
	for i := 0; i < len(data); i += 16 {
		// Offset
		sb.WriteString(fmt.Sprintf("%04x: ", i))

		// Hex bytes
		for j := 0; j < 16; j++ {
			if i+j < len(data) {
				sb.WriteString(fmt.Sprintf("%02x ", data[i+j]))
			} else {
				sb.WriteString("   ")
			}
			if j == 7 {
				sb.WriteString(" ")
			}
		}

		// ASCII representation
		sb.WriteString(" |")
		for j := 0; j < 16 && i+j < len(data); j++ {
			b := data[i+j]
			if b >= 32 && b < 127 {
				sb.WriteByte(b)
			} else {
				sb.WriteByte('.')
			}
		}
		sb.WriteString("|\n")
	}

	return sb.String()
}

